with with_prev as (select *, lag(paid_at) over (partition by order_id order by paid_at, id) as prev_paid_at from payments), gaps as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval 30 days then 1 else 0 end as is_new_session from with_prev), sessionized as (select *, sum(is_new_session) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as island_id from gaps) select s.id, s.order_id, s.method, s.amount, s.paid_at, s.status, s.is_new_session, (select avg(t2.quantity) from order_items t2 where t2.order_id = s.order_id) as avg_order_item_quantity from sessionized s order by is_new_session desc
